`
.script-book-v2-add-image-hint {
  position: relative;
  overflow: visible;
}
.script-book-v2-add-image-hint-btn {
  position: absolute;
  right: 2px;
  bottom: 0;
  font-size: 10px;
  color: #3b82f6;
  background: rgba(255, 255, 255, 0.92);
  padding: 1px 5px;
  border-radius: 3px;
  white-space: nowrap;
  opacity: 0;
  transition: opacity 0.12s;
  cursor: pointer;
  z-index: 10;
  font-family: inherit;
  line-height: 1.5;
  pointer-events: auto;
  border: none;
}
.script-book-v2-line-item:hover .script-book-v2-add-image-hint-btn {
  opacity: 1;
}
.script-book-v2-add-image-hint-btn:active {
  background: #bfdbfe;
}
/* 校对：行 hover 高亮 + 行首（字幕前）提示 */
.script-book-v2-line-item {
  position: relative;
  border-radius: 4px;
  transition: background-color 0.15s;
}
.script-book-v2-line-item:hover {
  background: rgba(79, 124, 255, 0.09);
  cursor: pointer;
}
.script-book-v2-edit-line-hint::after {
  content: "校对";
  position: absolute;
  top: 2px;
  left: 2px;
  font-size: 10px;
  color: #3b82f6;
  background: rgba(255, 255, 255, 0.92);
  padding: 1px 5px;
  border-radius: 3px;
  white-space: nowrap;
  opacity: 0;
  transition: opacity 0.12s;
  cursor: pointer;
  z-index: 10;
  font-family: inherit;
  line-height: 1.5;
  pointer-events: auto;
}
.script-book-v2-edit-line-hint:hover::after {
  opacity: 1;
}
.script-book-v2-edit-line-hint:active::after {
  background: #bfdbfe;
}
/* 保存后定位闪烁（时长较长，覆盖滚动到位所需时间） */
@keyframes script-book-v2-line-flash {
  0%, 100% { background: transparent; }
  10% { background: rgba(79, 124, 255, 0.2); }
  80% { background: rgba(79, 124, 255, 0.12); }
}
.script-book-v2-line-item--flash {
  animation: script-book-v2-line-flash 3.2s ease-out;
}
